import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useParams } from 'react-router-dom';

import { useBffData, usePageFilterApplied } from 'hooks';

import { FILTER_CONFIG_DEFINITION } from '../constants';
import { getBrandVolumeColor } from '../tabs/Definition/components/BrandAudience/constants';
import { mapInteractiveAudienceResponse } from '../tabs/Definition/components/BrandAudience/utils';
import {
  buildDemographicFilterValue,
  type DemographicGroupOptions,
} from '../tabs/Definition/components/ParticipationBreakdown/utils';
import { EMPTY_INTERACTIVE_SELECTION } from '../tabs/Definition/constants';
import {
  InteractiveAudienceType,
  InteractivePercentage,
  InteractiveRowSelection,
  InteractiveSelection,
} from '../tabs/Definition/types';

export const INTERACTIVE_DEBOUNCE_MS = 2000;

export const INTERACTIVE_AUDIENCE_BFF_ID =
  'consumer_one-yp_definition_brand-audience';

interface DebouncedRequest {
  audience: InteractiveAudienceType;
  selection: InteractiveSelection;
}

export interface UseDefinitionInteractiveAudienceResult {
  activeAudience: InteractiveAudienceType | null;
  selection: InteractiveSelection;
  highlightedItems: string[];
  isFetching: boolean;
  error: Error | null;
  hasResult: boolean;
  percentage: InteractivePercentage | null;
  selectAudience: (audience: InteractiveAudienceType) => void;
  toggleRow: (selection: InteractiveRowSelection) => void;
}

const EMPTY_GROUP_OPTIONS: DemographicGroupOptions = {
  gender: [],
  age: [],
  income: [],
};

export const useDefinitionInteractiveAudience = (
  groupOptions: DemographicGroupOptions = EMPTY_GROUP_OPTIONS,
): UseDefinitionInteractiveAudienceResult => {
  const { applied } = usePageFilterApplied(FILTER_CONFIG_DEFINITION.pageName);
  const { tab } = useParams();

  const [activeAudience, setActiveAudience] =
    useState<InteractiveAudienceType | null>(null);
  const [selection, setSelection] = useState<InteractiveSelection>(
    EMPTY_INTERACTIVE_SELECTION,
  );
  const [debounced, setDebounced] = useState<DebouncedRequest | null>(null);

  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const isComplete =
    !!activeAudience &&
    selection.gender.length > 0 &&
    selection.age.length > 0 &&
    selection.income.length > 0;

  const clearDebounceTimer = useCallback(() => {
    if (debounceTimer.current) {
      clearTimeout(debounceTimer.current);
      debounceTimer.current = null;
    }
  }, []);

  const reset = useCallback(() => {
    clearDebounceTimer();
    setActiveAudience(null);
    setSelection(EMPTY_INTERACTIVE_SELECTION);
    setDebounced(null);
  }, [clearDebounceTimer]);

  const selectAudience = useCallback(
    (audience: InteractiveAudienceType) => {
      clearDebounceTimer();
      setDebounced(null);
      setSelection(EMPTY_INTERACTIVE_SELECTION);
      setActiveAudience((prev) => (prev === audience ? null : audience));
    },
    [clearDebounceTimer],
  );

  const toggleRow = useCallback(
    ({ group, segment }: InteractiveRowSelection) => {
      if (!activeAudience) return;
      setSelection((prev) => {
        const current = prev[group];
        const exists = current.includes(segment);
        return {
          ...prev,
          [group]: exists
            ? current.filter((s) => s !== segment)
            : [...current, segment],
        };
      });
    },
    [activeAudience],
  );

  useEffect(() => {
    clearDebounceTimer();
    setDebounced(null);

    if (!isComplete || !activeAudience) return undefined;

    debounceTimer.current = setTimeout(() => {
      setDebounced({ audience: activeAudience, selection });
    }, INTERACTIVE_DEBOUNCE_MS);

    return clearDebounceTimer;
  }, [isComplete, activeAudience, selection, clearDebounceTimer]);

  const interactive = useBffData({
    id: INTERACTIVE_AUDIENCE_BFF_ID,
    kpiGroup: 'pos',
    subFilters: {
      country: applied?.country,
      product_type: applied?.segments,
      brand: applied?.audience_targeting_brands,
      competitor: applied?.audience_targeting_brands_comp,
      audience_type: debounced?.audience ?? null,
      gender: debounced
        ? buildDemographicFilterValue(
            debounced.selection.gender,
            groupOptions.gender,
          )
        : null,
      age: debounced
        ? buildDemographicFilterValue(debounced.selection.age, groupOptions.age)
        : null,
      socio_economic_level: debounced
        ? buildDemographicFilterValue(
            debounced.selection.income,
            groupOptions.income,
          )
        : null,
    },
    skipMainFilters: false,
    skipRequest: !debounced,
  });

  const filterSnapshot = JSON.stringify(applied ?? {});
  const prevSnapshot = useRef(filterSnapshot);
  useEffect(() => {
    if (prevSnapshot.current !== filterSnapshot) {
      prevSnapshot.current = filterSnapshot;
      reset();
    }
  }, [filterSnapshot, reset]);

  useEffect(() => {
    if (tab && tab !== 'definition') reset();
  }, [tab, reset]);

  const highlightedItems = useMemo(
    () => [...selection.gender, ...selection.age, ...selection.income],
    [selection],
  );

  const isDebouncing = isComplete && !debounced;
  const isFetching = isDebouncing || (!!debounced && interactive.loading);

  const error = debounced && !interactive.loading ? interactive.error : null;

  const hasResult = !!debounced && !interactive.loading && !interactive.error;

  const percentage = useMemo<InteractivePercentage | null>(() => {
    if (!debounced || interactive.loading || interactive.error) return null;
    const value = mapInteractiveAudienceResponse(
      interactive.data,
      debounced.audience,
    );
    if (value === null) return null;
    return {
      value,
      color: getBrandVolumeColor(value, debounced.audience === 'core'),
    };
  }, [debounced, interactive.data, interactive.loading, interactive.error]);

  return {
    activeAudience,
    selection,
    highlightedItems,
    isFetching,
    error,
    hasResult,
    percentage,
    selectAudience,
    toggleRow,
  };
};
